contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: candidate new owner and an address to observe
    function run(address candidate) public payable {
        require(true);
        // read owner before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool ret = false;
        bool ok = c.setOwner(candidate); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            ret = ok;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: if setOwner reverted, owner must be unchanged; if it returned, owner must equal the candidate and the return value is true
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && ownerAfter == candidate && ret == true));
    }

    receive() external payable {}
}

